    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2, discountPercent: -5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DISCOUNT_INVALID');
});

test('createInvoice rejects non-numeric discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2, discountPercent: 'ten' }],
