test('removeLine removes a line from invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'DEV-HOUR');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'UNKNOWN-SKU');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'LINE_NOT_FOUND');
});

test('removeLine returns NO_LINES when removing last line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'DEV-HOUR');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NO_LINES');
});

test('removeLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-12-15',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
      { sku: 'LOGO-PACK', qty: 1, name: 'Logo package', unitPrice: 120000, vatRate: 21 },
    ],
  };

  const removeResult = removeLine(invoice, 'DEV-HOUR');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const invoice = result.value;
  const originalLength = invoice.lines.length;

  removeLine(invoice, 'LOGO-PACK');

  assert.equal(invoice.lines.length, originalLength);
});

test('addLine can update multiple times', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  let invoice = result.value;

  // Add same SKU twice
  let addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(addResult.ok, true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 3);

  addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(addResult.ok, true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 8);
});

test('removeLine can remove from multi-line invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'LOGO-PACK');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 2);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(removeResult.value.lines[1].sku, 'STICKER');
});

test('issueInvoice assigns number and changes status to issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice = result.value;
  const issueResult = issueInvoice(invoice, []);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2025-0001');
  assert.equal(issueResult.value.status, 'issued');
});

test('issueInvoice calculates next number from existing numbers', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice = result.value;
  const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
  const issueResult = issueInvoice(invoice, existingNumbers);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2025-0003');
});

test('issueInvoice preserves invoice data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice = result.value;
  const issueResult = issueInvoice(invoice, []);

  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2025-12-15');
  assert.equal(issueResult.value.lines.length, 1);
  assert.equal(issueResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(issueResult.value.lines[0].qty, 2);
});

test('issueInvoice returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-12-15',
    status: 'issued',
    number: 'INV-2025-0001',
    lines: [{ sku: 'DEV-HOUR', qty: 2, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const issueResult = issueInvoice(invoice, []);

  assert.equal(issueResult.ok, false);
  assert.equal(issueResult.error, 'NOT_DRAFT');
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice = result.value;
  const originalStatus = invoice.status;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert(!invoice.number);
});

test('issueInvoice handles year boundary', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const invoice = result.value;
  const existingNumbers = ['INV-2025-9999'];
  const issueResult = issueInvoice(invoice, existingNumbers);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0001');
});

test('invoiceTotals clamps total to zero for 100% discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 21 }, // 10000, discount 10000, amount 0, vat 0
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 0); // No VAT on 0 amount
  assert.equal(totals.total, 0);
});

test('invoiceTotals handles fractional discounts with rounding', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, discountPercent: 33.33, vatRate: 21 }, // 300, discount ~99.99, amount ~200
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300);
  // 300 * 33.33 / 100 = 99.99, rounded to 100
  assert.equal(totals.discount, 100);
  // VAT on 200: 200 * 21 / 100 = 42
  assert.equal(totals.vat, 42);
  assert.equal(totals.total, 300 - 100 + 42);
});

test('invoiceTotals with 0% discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  // VAT: 10000 * 21 / 100 = 2100
  assert.equal(totals.vat, 2100);
  assert.equal(totals.total, 10000 + 2100);
});

test('createInvoice accepts 0% and 100% discounts', () => {
  const result1 = createInvoice({
