  assert.equal(totals.vat, 0); // No VAT on 0 amount
  assert.equal(totals.total, 0);
});

test('invoiceTotals handles fractional discounts with rounding', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, discountPercent: 33.33, vatRate: 21 }, // 300, discount ~99.99, amount ~200
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300);
  // 300 * 33.33 / 100 = 99.99, rounded to 100
  assert.equal(totals.discount, 100);
  // VAT on 200: 200 * 21 / 100 = 42
  assert.equal(totals.vat, 42);
  assert.equal(totals.total, 300 - 100 + 42);
});

