  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 100 }],
  });

  assert.equal(result1.ok, true);
  assert.equal(result2.ok, true);
});

test('invoiceTotals with mixed discount percentages', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }, // 100000, discount 10000, amount 90000, vat 18900
      { qty: 50, unitPrice: 1000, discountPercent: 20, vatRate: 21 }, // 50000, discount 10000, amount 40000, vat 8400
      { qty: 25, unitPrice: 1000, discountPercent: 0, vatRate: 21 }, // 25000, discount 0, amount 25000, vat 5250
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 175000);
  assert.equal(totals.discount, 20000);
  // VAT: 18900 + 8400 + 5250 = 32550
  assert.equal(totals.vat, 32550);
  assert.equal(totals.total, 175000 - 20000 + 32550);
});

test('createInvoice applies gold tier discount (5%)', () => {
  const result = createInvoice({
    customerId: 'C-008', // Lumen Records, gold tier
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 95000 cents
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.discount, 4750); // 95000 * 5 / 100
  // Amount after discount: 90250, VAT: 90250 * 21 / 100 = 18952.5 -> 18953
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 95000 - 4750 + 18953);
});

test('createInvoice applies silver tier discount (2.5%)', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 95000 cents
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.discount, 2375); // 95000 * 2.5 / 100
  // Amount after discount: 92625, VAT: 92625 * 21 / 100 = 19451.25 -> 19451
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 95000 - 2375 + 19451);
});

test('createInvoice applies standard tier discount (0%)', () => {
