  assert.equal(result.value.lines[0].discountPercent, 0);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.discount, 0);
  // VAT: 95000 * 21 / 100 = 19950
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 95000 + 19950);
});

test('createInvoice explicit discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-008', // Gold tier (5%)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }], // Explicit 10%
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.discount, 9500); // 95000 * 10 / 100
  assert.equal(totals.total, 85500);
});

test('createInvoice explicit 0% discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-008', // Gold tier (5%)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }], // Explicit 0%
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 95000);
});

test('createInvoice with multiple lines applies tier to all', () => {
  const result = createInvoice({
    customerId: 'C-008', // Gold tier (5%)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // No explicit discount
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }, // Explicit 10%
      { sku: 'STICKER', qty: 100 }, // No explicit discount
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // Tier discount
  assert.equal(result.value.lines[1].discountPercent, 10); // Explicit
  assert.equal(result.value.lines[2].discountPercent, 5); // Tier discount
});

test('addLine applies tier discount when not specified', () => {
  const result = createInvoice({
    customerId: 'C-003', // Silver tier (2.5%)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  let invoice = result.value;
  const addResult = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 }); // No discountPercent

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 2.5); // Silver tier discount
});

test('addLine explicit discount overrides tier', () => {
  const result = createInvoice({
    customerId: 'C-003', // Silver tier (2.5%)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  let invoice = result.value;
  const addResult = addLine(invoice, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 15); // Explicit discount
});

test('lineVat computes VAT on amount after discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Line total: 10000, discount: 1000, amount after discount: 9000
  // VAT: 9000 * 21 / 100 = 1890
  assert.equal(lineVat(line), 1890);
});

test('lineVat handles different VAT rates', () => {
  const line21 = { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const line9 = { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 9 };
  const line0 = { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 0 };

  // All have amount 10000 after no discount
  assert.equal(lineVat(line21), 2100); // 10000 * 21 / 100
  assert.equal(lineVat(line9), 900); // 10000 * 9 / 100
  assert.equal(lineVat(line0), 0); // 10000 * 0 / 100
});

test('lineVat rounds fractional VAT', () => {
  const line = { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  // Amount: 300, VAT: 300 * 21 / 100 = 63
  assert.equal(lineVat(line), 63);
});

test('invoiceTotals sums VAT from all lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }, // vat 2100
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 9 }, // vat 900
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // vat 0
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 3000); // 2100 + 900 + 0
});

test('invoiceTotals with mixed VAT rates and discounts', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }, // 100000, discount 10000, amount 90000, vat 18900
      { qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 9 }, // 10000, discount 0, amount 10000, vat 900
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 110000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 19800); // 18900 + 900
  assert.equal(totals.total, 110000 - 10000 + 19800);
});

test('invoiceTotals VAT is 0 when no lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 0);
});

test('invoiceTotals VAT computed per line and summed', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 99, discountPercent: 0, vatRate: 21 }, // 99, vat 20.79 -> 21
      { qty: 1, unitPrice: 99, discountPercent: 0, vatRate: 21 }, // 99, vat 20.79 -> 21
      { qty: 1, unitPrice: 99, discountPercent: 0, vatRate: 21 }, // 99, vat 20.79 -> 21
    ],
  };

  const totals = invoiceTotals(invoice);
  // Each line: 99 * 21 / 100 = 20.79 -> rounds to 21
  // Total VAT should be 21 + 21 + 21 = 63, not 297 * 21 / 100 = 62.37 -> 62
  assert.equal(totals.vat, 63);
});

